 "content": "def transform(grid):
    # Preserve the input and fill between paired guide pixels in rows/columns.
    # In each pair, intermediate background cells become color 2; guide cells
    # and unpaired cells stay unchanged.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    color = min(v for row in grid for v in row if v != bg)
    # Join all separated same-colored marks along a row or column when there
    # are exactly two marks in that line; inferred from the demo's paired endpoints.
    for r in range(h):
        xs = [c for c in range(w) if grid[r][c] == color]
        if len(xs) == 2 and xs[1] - xs[0] > 1:
            for c in range(xs[0] + 1, xs[1]):
                if grid[r][c] == bg: out[r][c] = 2
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c] == color]
        if len(ys) == 2 and ys[1] - ys[0] > 1:
            for r in range(ys[0] + 1, ys[1]):
                if grid[r][c] == bg: out[r][c] = 2
    return out
