 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    ink = min(v for row in grid for v in row if v != bg)

    # Detect the large rectangular frame represented by markers on its four
    # edges. The frame interior and horizontal/vertical spans are blue except
    # for the original ink markers.
    for top in range(h):
        for bottom in range(top + 2, h):
            for left in range(w):
                for right in range(left + 2, w):
                    if (grid[top][left] == ink and grid[top][right] == ink and
                        grid[bottom][left] == ink and grid[bottom][right] == ink):
                        # require at least one ink point on each side
                        if not all(any(grid[top][c] == ink for c in range(left+1,right)),
                                   any(grid[bottom][c] == ink for c in range(left+1,right)),
                                   any(grid[r][left] == ink for r in range(top+1,bottom)),
                                   any(grid[r][right] == ink for r in range(top+1,bottom))):
                            continue
