        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    fg = min((v for v in counts if v != bg), key=lambda v: counts[v])

    # The demonstrated operation paints missing positions where a sparse
    # repeated boundary motif is incomplete. Preserve all original markers.
    # Candidate motif cells are the non-field cells on the outer contour of
    # the marker bounding box, and any missing gaps in those rows/columns.
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == fg]
