 "content": "def transform(grid):
    """Recolor isolated background cells surrounded by the same marker color."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    colors = [v for v in counts if v != bg]
    ink = min(colors, key=lambda v: counts[v])
    out = [row[:] for row in grid]
    # A gap between two markers along a straight line is the new blue mark.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                continue
            horizontal = c > 0 and c + 1 < w and grid[r][c-1] == ink and grid[r][c+1] == ink
            vertical = r > 0 and r + 1 < h and grid[r-1][c] == ink and grid[r+1][c] == ink
            if horizontal or vertical:
                out[r][c] = 2
    return out
